interface Assignment {
  generation: number;
  partitions: number[];
}

declare function fetchAssignment(generation: number): Promise<Assignment>;

let currentGeneration = 0;
let ownedPartitions = new Set<number>();

async function rebalance(): Promise<void> {
  const requestedGeneration = ++currentGeneration;
  const assignment = await fetchAssignment(requestedGeneration);

  ownedPartitions = new Set(assignment.partitions);
}

interface MessageRecord {
  topic: string;
  partition: number;
  offset: string;
  value: Uint8Array;
}

type Commit = (input: {
  topic: string;
  partition: number;
  offset: string;
}) => Promise<void>;

declare const commit: Commit;
declare function handle(record: MessageRecord): Promise<void>;

async function processRecord(record: MessageRecord): Promise<void> {
  const nextOffset = (BigInt(record.offset) + 1n).toString();

  await commit({
    topic: record.topic,
    partition: record.partition,
    offset: nextOffset,
  });

  await handle(record);
}

interface MessageRecord {
  topic: string;
  partition: number;
  offset: string;
  value: Uint8Array;
}

declare function handle(record: MessageRecord): Promise<void>;
declare function commit(input: {
  topic: string;
  partition: number;
  offset: string;
}): Promise<void>;

async function processBatch(records: MessageRecord[]): Promise<void> {
  await Promise.all(records.map(async (record) => {
    await handle(record);

    const nextOffset = (BigInt(record.offset) + 1n).toString();
    await commit({
      topic: record.topic,
      partition: record.partition,
      offset: nextOffset,
    });
  }));
}
